function reqAsPromise<T>(req: IDBRequest<T>): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

/* ── Folios ─────────────────────────────────────────────────────── */

export async function loadFoliosFromIdb(): Promise<Folio[]> {
  if (!isBrowser()) return [];
  try {
    const db = await openDb();
    return reqAsPromise<Folio[]>(
      db.transaction("folios").objectStore("folios").getAll(),
    );
  } catch {
    return [];
  }
}

export async function saveFoliosToIdb(folios: Folio[]): Promise<void> {
  if (!isBrowser()) return;
  try {
    await tx("folios", "readwrite", async (t) => {
      const store = t.objectStore("folios");
      for (const f of folios) store.put(toStorable(f));
    });
  } catch {
    /* swallow — write failure shouldn't crash the writer */
  }
}

export async function deleteFolioFromIdb(id: string): Promise<void> {
  if (!isBrowser()) return;
  try {
    await tx(["folios", "folio-content"], "readwrite", async (t) => {
      t.objectStore("folios").delete(id);
      t.objectStore("folio-content").delete(id);
    });
  } catch {
    /* ignore */
  }
}

export async function saveFolioContentToIdb(
  folioId: string,
  html: string,
): Promise<void> {
  // Stamp when the snapshot is queued, not when an asynchronous read finishes.
  // An older in-flight save must not look newer than a departure mirror.
  const updatedAt = Date.now();
  await updateFolioContent(folioId, (previous) => ({
    folioId,
    html,
    format: "typst",
    ...(previous?.kit ? { kit: previous.kit } : {}),
    typstSource:
      previous?.typstSource !== undefined
        ? previous.html === html
          ? previous.typstSource
          : reconcileTypstSource(previous.typstSource, html)
        : htmlToTypst(html),
    updatedAt: previous?.html === html ? previous.updatedAt : updatedAt,
  }));
}

