export async function saveActiveFolioIdToIdb(id: string): Promise<void> {
  if (!isBrowser()) return;
  try {
    const rec: MetaRecord = {
      key: "active-folio-id",
      value: id,
      updatedAt: Date.now(),
    };
    await reqAsPromise(
      (await openDb())
